    gaps = {r: [c for c, v in enumerate(grid[r]) if v == 0] for r in bars}
    # The marker's column feeds the first perforated bar.
    starts = [c for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if starts:
        source = starts[0] % w
        for r in range(starts[0] // w + 1, bars[0]):
            out[r][source] = 2
    for i, r in enumerate(bars):
        holes = gaps[r]
        # Spread horizontally immediately above a bar to reach its openings.
        prev_cols = [source] if i == 0 and starts else []
        if i > 0:
            prev_cols = gaps[bars[i - 1]]
        vals = holes + prev_cols
        if len(holes) == 1 and i > 0:
            lo, hi = 0, w - 1
        else:
            lo, hi = min(vals), max(vals)
        if r > 0:
            for c in range(lo, hi + 1):
                out[r - 1][c] = 2
        for c in holes:
