        # Continue vertical paths through the open space to the next bar.
        if i + 1 < len(bars):
            nr = bars[i + 1]
            for rr in range(r + 1, nr - 1):
                for c in holes:
                    out[rr][c] = 2
    if bars:
        for rr in range(bars[-1] + 1, h):
            for c in gaps[bars[-1]]:
